function paperAccountTradeStatus(trade) {
  const labels = {SETTLED:"已退出",CLOSED:"已退出",OPEN:"持仓中",HOLDING:"持仓中",NO_FILL:"未买入",PLANNED:"计划待核验",
    MISSING_FROZEN:"冻结缺失 · 跳过",BUDGET_BELOW_ONE_LOT:"预算不足一手 · 跳过",FUTURE_ENTRY:"等待买入日",
    SKIPPED_NO_FILL:"未买入",SKIPPED_MISSING:"冻结缺失 · 跳过",MISSING_D_PUBLICATION:"冻结缺失 · 跳过",
    SKIPPED_INSUFFICIENT_CASH:"现金不足 · 跳过",INSUFFICIENT_CASH:"现金不足 · 跳过",
    PENDING_ENTRY:"等待买入日",PENDING_T:"等待买入日",NOT_DUE:"等待买入日",DEFERRED_AFTER_BLOCKER:"未续算 · 先核验缺口"};
  return labels[trade.status] || (String(trade.status).startsWith("NO_FILL") ? "未买入"
    : String(trade.status).startsWith("MISSING") ? "缺少证据" : trade.status || "待核验");
}

function paperAccountCurveSvg(days, narrow = typeof window !== "undefined" && window.innerWidth <= 600) {
  const points = days.filter(d => Number.isFinite(d.nav) && Number.isFinite(d.drawdown));
  if (!points.length) return '<p class="paper-intro">尚无可核验的连续净值，不绘制零收益线。</p>';
  const left=narrow?125:80,right=narrow?620:775,top=narrow?35:28,bottom=narrow?210:175,ddTop=narrow?290:226,ddBottom=narrow?370:286;
  const values=points.map(d=>d.nav), low=Math.min(735000,...values),high=Math.max(735000,...values);
  const padding=Math.max((high-low)*0.12,1000),ymin=low-padding,ymax=high+padding;
  const ddMin=Math.min(-0.005,...points.map(d=>d.drawdown));
  const x=i=>left+(right-left)*(points.length===1?0:i/(points.length-1));
  const y=v=>bottom-(v-ymin)/(ymax-ymin)*(bottom-top);
  const yd=v=>ddTop+(v/ddMin)*(ddBottom-ddTop);
  const line=(fn)=>points.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(2)},${fn(p).toFixed(2)}`).join(" ");
  const navPath=line(p=>y(p.nav)),ddPath=line(p=>yd(p.drawdown));
  const ticks=[ymin,(ymin+ymax)/2,ymax].map(v=>`<line x1="${left}" y1="${y(v)}" x2="${right}" y2="${y(v)}" stroke="#e2e9e6"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end">${(v/10000).toFixed(1)}万</text>`).join("");
  const first=escapeHtml(dateText(points[0].date)),last=escapeHtml(dateText(points.at(-1).date));
  return `<svg class="${narrow?"paper-narrow-chart":"paper-wide-chart"}" viewBox="${narrow?"0 0 640 430":"0 0 800 320"}" role="img" aria-label="已知交易模拟账户净值及收盘回撤，${first}至${last}。逐日数值见下方展开表格。">
    ${ticks}<line x1="${left}" y1="${y(735000)}" x2="${right}" y2="${y(735000)}" stroke="#9bada6" stroke-dasharray="5 4"/>
    <path d="${navPath}" fill="none" stroke="#21735f" stroke-width="3"/>
    <circle cx="${x(points.length-1)}" cy="${y(points.at(-1).nav)}" r="3.5" fill="#21735f"/>
    <text x="${left}" y="${bottom+(narrow?32:21)}">${first}</text><text x="${right}" y="${bottom+(narrow?32:21)}" text-anchor="end">${last}</text>
    <text x="${left}" y="${ddTop-(narrow?16:10)}">收盘净值回撤</text><line x1="${left}" y1="${ddTop}" x2="${right}" y2="${ddTop}" stroke="#dce3df"/>
    <text x="${left-10}" y="${ddTop+4}" text-anchor="end">0%</text><text x="${left-10}" y="${ddBottom+4}" text-anchor="end">${(ddMin*100).toFixed(2)}%</text>
    <path d="${ddPath} L${x(points.length-1)},${ddTop} L${left},${ddTop} Z" fill="#dca15d" opacity=".18"/>
    <path d="${ddPath}" fill="none" stroke="#ac741e" stroke-width="2"/>
  </svg>`;
}

